// Command gen turns internal/rules/packs/*.yaml into internal/rules/packs_gen.go,
// so the hook binary carries the packs as Go literals and never parses YAML.
// Run it with `go generate ./internal/rules`. It validates every pack first
// (regexes included), so an invalid pack never reaches the generated file.
//
// The output holds only slices and struct literals of strings, ints, bools
// and the address of one package-level bool: static data, no init work.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"io/fs"
	"os"
	"path/filepath"
	"strconv"

	"github.com/Panda-Taps-LLC/watchdeck/internal/rules"
)

func main() {
	dir := flag.String("dir", ".", "the internal/rules directory")
	flag.Parse()
	src, err := Generate(os.DirFS(*dir))
	if err != nil {
		fmt.Fprintln(os.Stderr, "gen:", err)
		os.Exit(1)
	}
	if err := os.WriteFile(filepath.Join(*dir, "packs_gen.go"), src, 0o644); err != nil {
		fmt.Fprintln(os.Stderr, "gen:", err)
		os.Exit(1)
	}
}

// Generate returns the gofmt'd source of packs_gen.go for packs/*.yaml in fsys.
func Generate(fsys fs.FS) ([]byte, error) {
	packs, err := rules.LoadFS(fsys)
	if err != nil {
		return nil, err
	}
	var b bytes.Buffer
	q := strconv.Quote
	b.WriteString("// Code generated by internal/rules/gen from packs/*.yaml; DO NOT EDIT.\n\n")
	b.WriteString("package rules\n\n")
	b.WriteString("// packOff is what a pack's `enabled: false` points at.\nvar packOff = false\n\n")
	b.WriteString("// genPacks is packs/*.yaml as Go literals, in file-name order.\nvar genPacks = []Pack{\n")
	for _, p := range packs {
		fmt.Fprintf(&b, "{\nName: %s,\nVersion: %d,\nDescription: %s,\n", q(p.Name), p.Version, q(p.Description))
		if !p.EnabledByDefault() {
			b.WriteString("Enabled: &packOff,\n")
		}
		b.WriteString("Rules: []Rule{\n")
		for _, r := range p.Rules {
			fmt.Fprintf(&b, "{\nID: %s,\nTool: %s,\nMatch: Match{", q(r.ID), q(r.Tool))
			m := r.Match
			if m.Field != "" {
				fmt.Fprintf(&b, "Field: %s, ", q(m.Field))
			}
			if m.Regex != "" {
				fmt.Fprintf(&b, "Regex: %s, ", strconv.Quote(m.Regex))
			}
			if len(m.Literals) > 0 {
				fmt.Fprintf(&b, "Literals: %s, ", strs(m.Literals))
			}
			if len(m.Argv0) > 0 {
				fmt.Fprintf(&b, "Argv0: %s, ", strs(m.Argv0))
			}
			if m.Anchored {
				b.WriteString("Anchored: true, ")
			}
			fmt.Fprintf(&b, "},\nSeverity: %s,\nAction: %s,\nDescription: %s,\nFPNote: %s,\n},\n",
				q(string(r.Severity)), q(string(r.Action)), q(r.Description), q(r.FPNote))
		}
		b.WriteString("},\n},\n")
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}

func strs(ss []string) string {
	var b bytes.Buffer
	b.WriteString("[]string{")
	for i, s := range ss {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(strconv.Quote(s))
	}
	b.WriteString("}")
	return b.String()
}
